using Payments;

namespace PaymentGateway.Tests;

[TestClass]
public sealed class PaymentGatewayTests
{
    private readonly Payments.PaymentGateway _sut = new();

    // --- ChargeAsync ---

    [TestMethod]
    [DataRow("tok_valid_visa", 49.99)]
    [DataRow("tok_valid_mc", 0.01)]
    [DataRow("tok_valid_amex", 9999.99)]
    [DisplayName("ChargeAsync – valid token and amount returns success with non-empty ChargeId")]
    public async Task ChargeAsync_ValidTokenAndAmount_ReturnsSuccessWithChargeId(string token, double amount)
    {
        var result = await _sut.ChargeAsync(token, (decimal)amount);

        Assert.IsTrue(result.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(result.ChargeId), "ChargeId must not be null or empty");
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    [DisplayName("ChargeAsync – null or empty token throws ArgumentException")]
    public async Task ChargeAsync_NullOrEmptyToken_ThrowsArgumentException(string? token)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _sut.ChargeAsync(token!, 10.00m));
    }

    [TestMethod]
    [DataRow(0.0)]
    [DataRow(-5.0)]
    [DisplayName("ChargeAsync – zero or negative amount throws ArgumentOutOfRangeException")]
    public async Task ChargeAsync_ZeroOrNegativeAmount_ThrowsArgumentOutOfRangeException(double amount)
    {
        await Assert.ThrowsExceptionAsync<ArgumentOutOfRangeException>(
            () => _sut.ChargeAsync("tok_valid", (decimal)amount));
    }

    [TestMethod]
    [DisplayName("ChargeAsync – declined card returns Success=false")]
    public async Task ChargeAsync_DeclinedCard_ReturnsFailure()
    {
        var result = await _sut.ChargeAsync("tok_declined", 50.00m);

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DisplayName("ChargeAsync – each call produces a unique ChargeId")]
    public async Task ChargeAsync_MultipleCalls_ProducesUniqueChargeIds()
    {
        var result1 = await _sut.ChargeAsync("tok_valid", 10.00m);
        var result2 = await _sut.ChargeAsync("tok_valid", 10.00m);

        Assert.AreNotEqual(result1.ChargeId, result2.ChargeId,
            "Each charge should produce a unique identifier");
    }

    // --- RefundAsync ---

    [TestMethod]
    [DisplayName("RefundAsync – valid chargeId returns success with non-empty RefundId")]
    public async Task RefundAsync_ValidChargeId_ReturnsSuccessWithRefundId()
    {
        // Arrange – first create a charge to refund
        var charge = await _sut.ChargeAsync("tok_valid", 25.00m);
        Assert.IsTrue(charge.Success, "Prerequisite charge must succeed");

        // Act
        var refund = await _sut.RefundAsync(charge.ChargeId);

        // Assert
        Assert.IsTrue(refund.Success);
        Assert.IsFalse(string.IsNullOrWhiteSpace(refund.RefundId), "RefundId must not be null or empty");
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    [DisplayName("RefundAsync – null or empty chargeId throws ArgumentException")]
    public async Task RefundAsync_NullOrEmptyChargeId_ThrowsArgumentException(string? chargeId)
    {
        await Assert.ThrowsExceptionAsync<ArgumentException>(
            () => _sut.RefundAsync(chargeId!));
    }

    [TestMethod]
    [DisplayName("RefundAsync – non-existent chargeId returns Success=false")]
    public async Task RefundAsync_NonExistentChargeId_ReturnsFailure()
    {
        var result = await _sut.RefundAsync("ch_does_not_exist");

        Assert.IsFalse(result.Success);
    }

    [TestMethod]
    [DisplayName("RefundAsync – double refund of same charge returns failure on second attempt")]
    public async Task RefundAsync_DoubleRefund_SecondAttemptFails()
    {
        var charge = await _sut.ChargeAsync("tok_valid", 30.00m);
        Assert.IsTrue(charge.Success, "Prerequisite charge must succeed");

        var firstRefund = await _sut.RefundAsync(charge.ChargeId);
        Assert.IsTrue(firstRefund.Success, "First refund should succeed");

        var secondRefund = await _sut.RefundAsync(charge.ChargeId);

        Assert.IsFalse(secondRefund.Success, "Duplicate refund should fail");
    }
}

